{{ config(materialized='table') }}

with
quarantined as (
    select
        order_id,
        line_number,
        customer_business_key,
        product_code,
        line_order_date,
        line_quantity,
        line_revenue,
        line_list_value,
        violation_00
    from {{ ref("ecommerce__order_summary__checked") }}
),
violations as (
    select
        'order_id_not_null' as rule_name,
        order_id,
        line_number,
        customer_business_key,
        product_code,
        line_order_date,
        line_quantity,
        line_revenue,
        line_list_value
    from quarantined
    where violation_00
)

select
    rule_name,
    order_id,
    line_number,
    customer_business_key,
    product_code,
    line_order_date,
    line_quantity,
    line_revenue,
    line_list_value
from violations
